package com.opsbridge;
import com.twilio.Twilio;
import com.twilio.rest.api.v2010.account.Message;
import com.twilio.type.PhoneNumber;
import com.sendgrid.SendGrid;
import com.sendgrid.Request;
import com.sendgrid.Method;
import com.sendgrid.Response;
import com.sendgrid.helpers.mail.Mail;
import com.sendgrid.helpers.mail.objects.Email;
import com.sendgrid.helpers.mail.objects.Content;
import org.springframework.web.client.RestClient;
import org.springframework.http.MediaType;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.*;
import java.io.IOException;
import java.util.*;
@RestController @RequestMapping("/api/v1/integrations")
public class IntegrationController {
 private final ObjectMapper mapper=new ObjectMapper();
 private final VodexClient vodexClient;
 private final VapiClient vapiClient;
 private final VoiceCallPolicy voiceCallPolicy;
 private final VoiceConsentClient voiceConsentClient;
 public IntegrationController(VodexClient vodexClient,VapiClient vapiClient,VoiceCallPolicy voiceCallPolicy,VoiceConsentClient voiceConsentClient){this.vodexClient=vodexClient;this.vapiClient=vapiClient;this.voiceCallPolicy=voiceCallPolicy;this.voiceConsentClient=voiceConsentClient;}
 @Value("${opsbridge.twilio.account-sid:}") private String twilioSid; @Value("${opsbridge.twilio.auth-token:}") private String twilioToken; @Value("${opsbridge.twilio.whatsapp-from:}") private String whatsappFrom;
 @Value("${opsbridge.whatsapp-cloud.access-token:}") private String whatsappCloudToken; @Value("${opsbridge.whatsapp-cloud.phone-number-id:}") private String whatsappCloudPhoneNumberId; @Value("${opsbridge.whatsapp-cloud.graph-api-version:v27.0}") private String whatsappCloudApiVersion;
 @Value("${opsbridge.sendgrid.api-key:}") private String sendgridKey; @Value("${opsbridge.sendgrid.from:}") private String sendgridFrom;
 @Value("${opsbridge.google.client-id:}") private String googleClientId; @Value("${opsbridge.microsoft.client-id:}") private String microsoftClientId; @Value("${opsbridge.docusign.integration-key:}") private String docusignKey;
 @Value("${opsbridge.google.access-token:}") private String googleAccessToken; @Value("${opsbridge.microsoft.access-token:}") private String microsoftAccessToken; @Value("${opsbridge.docusign.access-token:}") private String docusignAccessToken; @Value("${opsbridge.docusign.base-uri}") private String docusignBaseUri; @Value("${opsbridge.docusign.account-id:}") private String docusignAccountId; @Value("${opsbridge.vapi.api-key:}") private String vapiKey;
 public record WhatsAppRequest(@NotBlank String to,@NotBlank String message,boolean consent){} public record WhatsAppTemplateRequest(@NotBlank String to,@NotBlank String templateName,@NotBlank String language,boolean consent){} public record EmailRequest(@jakarta.validation.constraints.Email @NotBlank String to,@NotBlank String subject,@NotBlank String message){}
 @GetMapping public Map<String,Object> catalog(){return Map.of("items",List.of(connector("stripe",System.getenv("STRIPE_SECRET_KEY")),connector("whatsapp",twilioSid),connector("whatsapp-cloud",whatsappCloudToken),connector("email",sendgridKey),connector("google-drive",googleAccessToken),connector("microsoft-graph",microsoftAccessToken),connector("docusign",docusignAccessToken),connector("vapi",vapiKey),connector("vodex",vodexClient.isConfigured())));}
 private Map<String,Object> connector(String name,String secret){return Map.of("id",name,"configured",secret!=null&&!secret.isBlank(),"mode","sandbox");}
 private Map<String,Object> connector(String name,boolean configured){return Map.of("id",name,"configured",configured,"mode","sandbox");}
 @PostMapping("/whatsapp/messages") @ResponseStatus(HttpStatus.ACCEPTED) public Map<String,String> sendWhatsApp(@Valid @RequestBody WhatsAppRequest request,@RequestHeader("X-Tenant-Id") String tenant){if(!request.consent())throw new IllegalArgumentException("Documented customer consent is required before sending WhatsApp messages.");if(twilioSid.isBlank()||twilioToken.isBlank()||whatsappFrom.isBlank())throw new IllegalStateException("Twilio WhatsApp sandbox is not configured.");Twilio.init(twilioSid,twilioToken);Message sent=Message.creator(new PhoneNumber("whatsapp:"+request.to()),new PhoneNumber(whatsappFrom.startsWith("whatsapp:")?whatsappFrom:"whatsapp:"+whatsappFrom),request.message()).create();return Map.of("provider","twilio","messageId",sent.getSid(),"status",sent.getStatus().toString(),"tenantId",tenant);}
 @PostMapping("/whatsapp-cloud/templates") @ResponseStatus(HttpStatus.ACCEPTED) public Map<?,?> sendWhatsAppCloudTemplate(@Valid @RequestBody WhatsAppTemplateRequest request,@RequestHeader("X-Tenant-Id") String tenant){if(!request.consent())throw new IllegalArgumentException("Documented customer consent is required before sending WhatsApp messages.");if(whatsappCloudToken.isBlank()||whatsappCloudPhoneNumberId.isBlank())throw new IllegalStateException("WhatsApp Cloud API credentials are not configured.");var body=Map.of("messaging_product","whatsapp","to",request.to(),"type","template","template",Map.of("name",request.templateName(),"language",Map.of("code",request.language())));var result=RestClient.create().post().uri("https://graph.facebook.com/{version}/{phoneNumberId}/messages",whatsappCloudApiVersion,whatsappCloudPhoneNumberId).contentType(MediaType.APPLICATION_JSON).header("Authorization","Bearer "+whatsappCloudToken).body(body).retrieve().body(Map.class);return result==null?Map.of("provider","whatsapp-cloud","status","accepted","tenantId",tenant):Map.of("provider","whatsapp-cloud","tenantId",tenant,"result",result);}
 @PostMapping("/email") @ResponseStatus(HttpStatus.ACCEPTED) public Map<String,String> sendEmail(@Valid @RequestBody EmailRequest input,@RequestHeader("X-Tenant-Id") String tenant)throws IOException{if(sendgridKey.isBlank()||sendgridFrom.isBlank())throw new IllegalStateException("SendGrid credentials are not configured.");Mail mail=new Mail(new Email(sendgridFrom),input.subject(),new Email(input.to()),new Content("text/plain",input.message()));Request request=new Request();request.setMethod(Method.POST);request.setEndpoint("mail/send");request.setBody(mail.build());Response response=new SendGrid(sendgridKey).api(request);if(response.getStatusCode()>=400)throw new IllegalStateException("Email provider rejected the request.");return Map.of("provider","sendgrid","status","accepted","tenantId",tenant);}
 public record DriveUpload(@NotBlank String name,@NotBlank String content){}
 @PostMapping("/google-drive/files") @ResponseStatus(HttpStatus.CREATED) public Map<?,?> uploadDriveText(@Valid @RequestBody DriveUpload input,@RequestHeader("X-Tenant-Id") String tenant)throws Exception{if(googleAccessToken.isBlank())throw new IllegalStateException("Google Drive OAuth access token is not configured.");var metadata=Map.of("name",input.name(),"mimeType","text/plain","appProperties",Map.of("opsbridgeTenant",tenant));String boundary="opsbridge_"+UUID.randomUUID().toString().replace("-","");String body="--"+boundary+"\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n"+mapper.writeValueAsString(metadata)+"\r\n--"+boundary+"\r\nContent-Type: text/plain; charset=UTF-8\r\n\r\n"+input.content()+"\r\n--"+boundary+"--";var response=RestClient.create().post().uri("https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&fields=id,name,webViewLink").contentType(MediaType.parseMediaType("multipart/related; boundary="+boundary)).header("Authorization","Bearer "+googleAccessToken).body(body).retrieve().body(Map.class);return response==null?Map.of("provider","google-drive","status","accepted"):response;}
 public record GraphMail(@NotBlank String to,@NotBlank String subject,@NotBlank String content){}
 @PostMapping("/microsoft-graph/mail") @ResponseStatus(HttpStatus.ACCEPTED) public Map<String,Object> sendGraphMail(@Valid @RequestBody GraphMail input,@RequestHeader("X-Tenant-Id") String tenant){if(microsoftAccessToken.isBlank())throw new IllegalStateException("Microsoft Graph OAuth access token is not configured.");var body=Map.of("message",Map.of("subject",input.subject(),"body",Map.of("contentType","Text","content",input.content()),"toRecipients",List.of(Map.of("emailAddress",Map.of("address",input.to())))),"saveToSentItems",true);RestClient.create().post().uri("https://graph.microsoft.com/v1.0/me/sendMail").contentType(MediaType.APPLICATION_JSON).header("Authorization","Bearer "+microsoftAccessToken).body(body).retrieve().toBodilessEntity();return Map.of("provider","microsoft-graph","status","accepted","tenantId",tenant);}
 @PostMapping("/docusign/envelopes/draft") @ResponseStatus(HttpStatus.CREATED) public Map<?,?> createEnvelopeDraft(@RequestBody Map<String,Object> envelope,@RequestHeader("X-Tenant-Id") String tenant){if(docusignAccessToken.isBlank()||docusignAccountId.isBlank())throw new IllegalStateException("DocuSign OAuth access token and account ID are not configured.");Map<String,Object> draft=new HashMap<>(envelope);draft.put("status","created");var result=RestClient.create().post().uri(docusignBaseUri+"/restapi/v2.1/accounts/"+docusignAccountId+"/envelopes").contentType(MediaType.APPLICATION_JSON).header("Authorization","Bearer "+docusignAccessToken).body(draft).retrieve().body(Map.class);return result==null?Map.of("provider","docusign","status","draft","tenantId",tenant):result;}
 public record VoiceCall(@NotBlank @jakarta.validation.constraints.Pattern(regexp="^\\+[1-9][0-9]{6,14}$",message="Use an E.164 phone number.") String customerNumber){}
 @PostMapping("/voice/calls") @ResponseStatus(HttpStatus.ACCEPTED) public Map<?,?> startVoiceCall(@Valid @RequestBody VoiceCall input,@RequestHeader("X-Tenant-Id") String tenant){voiceCallPolicy.assertWindowAllowed(tenant);voiceConsentClient.requireEligible(tenant,input.customerNumber());return vapiClient.startCall(tenant,input.customerNumber());}
 @PostMapping("/vodex/calls") @ResponseStatus(HttpStatus.ACCEPTED) public Map<String,Object> startVodexCall(@Valid @RequestBody VodexClient.TriggerCallRequest input,@RequestHeader("X-Tenant-Id") String tenant){var result=vodexClient.triggerCall(input);return Map.of("provider","vodex","tenantId",tenant,"result",result);}
 @GetMapping("/vodex/calls/{callUuid}/transcript") public Map<String,Object> getVodexTranscript(@PathVariable String callUuid,@RequestHeader("X-Tenant-Id") String tenant){return Map.of("provider","vodex","tenantId",tenant,"transcript",vodexClient.getTranscript(callUuid));}
}
